module rsa_encrypt #(parameter WIDTH = 8) (  
    input clk,  
    input reset,  
    input [WIDTH-1:0] plaintext,  
    input [WIDTH-1:0] n,  
    input [WIDTH-1:0] e,  
    output reg [WIDTH-1:0] ciphertext  
);  
    reg [WIDTH-1:0] intermediate;  
    reg [WIDTH-1:0] power;  
    reg [3:0] state;  

    localparam IDLE = 0, COMPUTE = 1, MODULUS = 2, DONE = 3;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            state <= IDLE;  
            ciphertext <= 0;  
            intermediate <= 0;  
            power <= 1;  
        end else begin  
            case (state)  
                IDLE: begin  
                    power <= e;  
                    intermediate <= plaintext;  
                    state <= COMPUTE;  
                end  
                COMPUTE: begin  
                    if (power > 0) begin  
                        intermediate <= (intermediate * plaintext);  
                        power <= power - 1;  
                    end else begin  
                        state <= MODULUS;  
                    end  
                end  
                MODULUS: begin  
                    ciphertext <= intermediate % n;  
                    state <= DONE;  
                end  
                DONE: begin  
                    // Output is ready  
                end  
            endcase  
        end  
    end  
endmodule

