module dma_controller(  
    input clk,  
    input reset,  
    input [1:0] channel_enable, // 2 channels  
    input start_transfer,  
    output reg [1:0] channel_status // 0: idle, 1: busy  
);  
    reg [1:0] state;  
    localparam IDLE = 2'b00, TRANSFER = 2'b01;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            channel_status <= 2'b00;  
            state <= IDLE;  
        end else begin  
            case (state)  
                IDLE: begin  
                    if (start_transfer) begin  
                        channel_status <= channel_enable;  
                        state <= TRANSFER;  
                    end  
                end  
                TRANSFER: begin  
                    channel_status <= 2'b00; // Transfer complete  
                    state <= IDLE;  
                end  
            endcase  
        end  
    end  
endmodule

