    always @(posedge clk or posedge rst) begin
        if (rst) begin
            accept <= 0;
            last_accepted <= 0;
        end else begin
            if ((src_ip >= 32'hC0A80101) && (src_ip <= 32'hC0A8010A) && (dst_port == 16'd80)) begin
                accept <= 1;
                last_accepted <= 1;
            end else begin
                accept <= 0;
                last_accepted <= 0;
            end
        end
    end
endmodule

