module uart_transmitter (
    input wire clk,
    input wire reset,
    input wire start_transmit,
    input wire [7:0] data_in,
    output reg tx,
    output reg ready
);
    parameter CLK_FREQ = 50000000; // 50 MHz clock frequency
    parameter BAUD_RATE = 9600;
    parameter CLOCKS_PER_BIT = CLK_FREQ / BAUD_RATE;

    reg [3:0] bit_index;
    reg [15:0] clk_counter;
    reg transmitting;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            tx <= 1;
            ready <= 1;
            bit_index <= 0;
            clk_counter <= 0;
            transmitting <= 0;
        end else if (start_transmit && ready) begin
            transmitting <= 1;
            ready <= 0;
            bit_index <= 0;
            clk_counter <= 0;
        end else if (transmitting) begin
            if (clk_counter < CLOCKS_PER_BIT - 1) begin
                clk_counter <= clk_counter + 1;
            end else begin
                clk_counter <= 0;
                if (bit_index == 0) begin
                    tx <= 0; // start bit
                end else if (bit_index <= 8) begin
                    tx <= data_in[bit_index - 1]; // data bits
                end else if (bit_index == 9) begin
                    tx <= 1; // stop bit
                end else begin
                    transmitting <= 0; // transmission complete
                    ready <= 1; // ready for new data
                end
                bit_index <= bit_index + 1;
            end
        end
    end
endmodule

