module sqrt_cordic (  
    input clk,  
    input rst,  
    input en,  
    input [15:0] x,  
    output reg [15:0] sqrt_out,  
    output reg ready  
);  
    reg [15:0] x_reg;  
    reg [15:0] z;  
    reg [3:0] i;  
    reg [15:0] angle [0:15];  
    initial begin  
        angle[0] = 16'h1;  
        angle[1] = 16'h2;  
        angle[2] = 16'h4;  
        angle[3] = 16'h8;  
        angle[4] = 16'h10;  
        angle[5] = 16'h20;  
        angle[6] = 16'h40;  
        angle[7] = 16'h80;  
        angle[8] = 16'h100;  
        angle[9] = 16'h200;  
        angle[10] = 16'h400;  
        angle[11] = 16'h800;  
        angle[12] = 16'h1000;  
        angle[13] = 16'h2000;  
        angle[14] = 16'h4000;  
        angle[15] = 16'h8000;  
    end  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            sqrt_out <= 0;  
            ready <= 0;  
            i <= 0;  
        end else if (en) begin  
            if (i < 16) begin  
                if (i == 0) begin  
                    x_reg <= x;  
                    z <= x >> 1;  
                end else begin  
                    x_reg <= x_reg - (z >> i);  
                    z <= z + (x_reg >> (i + 1));  
                end  
                i <= i + 1;  
                ready <= 0;  
            end else begin  
                sqrt_out <= z;  
                ready <= 1;  
            end  
        end  
    end  
endmodule

