module branch_predictor (
    input wire clk,
    input wire reset,
    input wire branch_outcome, // 1 for taken, 0 for not taken
    output reg [1:0] predictor_state // 2-bit state
);

    // State encoding
    parameter STRONGLY_NOT_TAKEN = 2'b00;
    parameter WEAKLY_NOT_TAKEN = 2'b01;
    parameter WEAKLY_TAKEN = 2'b10;
    parameter STRONGLY_TAKEN = 2'b11;

    // Update the predictor state on the rising edge of clk or reset
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            predictor_state <= STRONGLY_NOT_TAKEN; // Reset to strongly not taken
        end else begin
            case (predictor_state)
                STRONGLY_NOT_TAKEN: begin
                    if (branch_outcome) 
                        predictor_state <= WEAKLY_NOT_TAKEN;
                end
                WEAKLY_NOT_TAKEN: begin
                    if (branch_outcome) 
                        predictor_state <= WEAKLY_TAKEN;
                    else 
                        predictor_state <= STRONGLY_NOT_TAKEN;
                end
                WEAKLY_TAKEN: begin
                    if (branch_outcome) 
                        predictor_state <= STRONGLY_TAKEN;
                    else 
                        predictor_state <= WEAKLY_NOT_TAKEN;
                end
                STRONGLY_TAKEN: begin
                    if (~branch_outcome) 
                        predictor_state <= WEAKLY_TAKEN;
                end
            endcase
        end
    end
endmodule

