module dma_controller(
    input clk,
    input reset,
    input start,
    input [7:0] src_addr,
    input [7:0] dst_addr,
    input [7:0] transfer_size,
    output reg transfer_done
);
    reg [7:0] current_size;
    reg [1:0] state; // 0: idle, 1: transferring, 2: done
    parameter IDLE = 2'b00, TRANSFERRING = 2'b01, DONE = 2'b10;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= IDLE;
            current_size <= 0;
            transfer_done <= 0;
        end else begin
            case (state)
                IDLE: begin
                    transfer_done <= 0;
                    if (start) begin
                        current_size <= transfer_size;
                        state <= TRANSFERRING;
                    end
                end
                TRANSFERRING: begin
                    if (current_size > 0) begin
                        // Simulate data transfer from src_addr to dst_addr
                        current_size <= current_size - 1;
                    end else begin
                        state <= DONE;
                    end
                end
                DONE: begin
                    transfer_done <= 1;
                    if (!start) begin
                        state <= IDLE; // Go back to idle if not starting
                    end
                end
            endcase
        end
    end
endmodule

