module cache_controller (  
    input wire clk,  
    input wire reset,  
    input wire [7:0] address,  
    input wire read,  
    input wire write,  
    output reg hit,  
    output reg [7:0] data_out  
);  
    reg [7:0] cache_data [3:0];  
    reg [7:0] cache_tag [3:0];  
    reg valid [3:0];  
    reg [1:0] lru_counter [3:0];  
    integer i, lru_index;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            for (i = 0; i < 4; i = i + 1) begin  
                valid[i] <= 0;  
                lru_counter[i] <= 2'b00;  
            end  
            hit <= 0;  
            data_out <= 0;  
        end else begin  
            if (read) begin  
                hit <= 0;  
                for (i = 0; i < 4; i = i + 1) begin  
                    if (valid[i] && cache_tag[i] == address[7:2]) begin  
                        hit <= 1;  
                        data_out <= cache_data[i];  
                        lru_counter[i] <= 2'b11;  // most recently used  
                    end else begin  
                        lru_counter[i] <= lru_counter[i] >> 1;  // shift LRU counter  
                    end  
                end  
                if (!hit) begin  
                    lru_index = 0;  
                    for (i = 1; i < 4; i = i + 1) begin  
                        if (lru_counter[i] < lru_counter[lru_index])  
                            lru_index = i;  
                    end  
                    cache_tag[lru_index] = address[7:2];  
                    cache_data[lru_index] = 8'hFF;  // example data  
                    valid[lru_index] = 1;  
                    lru_counter[lru_index] = 2'b11;  
                end  
            end else if (write) begin  
                lru_index = 0;  
                for (i = 0; i < 4; i = i + 1) begin  
                    if (valid[i] && cache_tag[i] == address[7:2]) begin  
                        cache_data[i] <= 8'hAA;  // example write data  
                        lru_counter[i] <= 2'b11;  // most recently used  
                    end else begin  
                        lru_counter[i] <= lru_counter[i] >> 1;  // shift LRU counter  
                    end  
                end  
                // If not hit, replace LRU  
                if (!valid[lru_index] || lru_counter[lru_index] == 0) begin  
                    cache_tag[lru_index] = address[7:2];  
                    cache_data[lru_index] = 8'hAA;  // example write data  
                    valid[lru_index] = 1;  
                    lru_counter[lru_index] = 2'b11;  
                end  
            end  
        end  
    end  
endmodule

