module adaptive_lms_filter #(parameter N = 4) (  
    input clk,  
    input reset,  
    input signed [15:0] x,         // Input signal  
    input signed [15:0] d,         // Desired signal  
    input signed [15:0] mu,        // Step size  
    output reg signed [15:0] y      // Output signal  
);  
    reg signed [15:0] w [0:N-1];    // Coefficients  
    reg signed [15:0] error;         // Error signal  
    reg signed [15:0] x_delayed;     // Delayed input signal  
    integer i;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            for (i = 0; i < N; i = i + 1)  
                w[i] <= 16'b0;  
            y <= 16'b0;  
        end else begin  
            // Shift input signal  
            x_delayed <= x;  
            // Compute output  
            y <= 0;  
            for (i = 0; i < N; i = i + 1)  
                y <= y + (w[i] * x_delayed);  
            // Compute error  
            error <= d - y;  
            // Update coefficients  
            for (i = 0; i < N; i = i + 1)  
                w[i] <= w[i] + (mu * error * x_delayed);  
        end  
    end  
endmodule

