module siso_shift_register #(parameter WIDTH = 5) (
    input clk,
    input reset,
    input serial_in,
    output reg serial_out
);
    reg [WIDTH-1:0] shift_reg;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            shift_reg <= 0;
            serial_out <= 0;
        end else begin
            serial_out <= shift_reg[0];
            shift_reg <= {serial_in, shift_reg[WIDTH-1:1]};
        end
    end
endmodule

