module PLL (  
    input wire clk,  // input clock signal  
    input wire rst,  // active high reset  
    input wire ref_freq,  // reference frequency  
    output reg vco_out,  // VCO output clock  
    output wire divided_clk  // divided clock output  
);  

    reg [3:0] phase_error;  // phase comparator error  
    reg [3:0] loop_filter;  // loop filter output  
    reg [3:0] vco_frequency;  // VCO frequency setting  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            phase_error <= 4'b0;  
            loop_filter <= 4'b0;  
            vco_frequency <= 4'b0;  
            vco_out <= 1'b0;  
        end else begin  
            // Phase comparator logic  
            phase_error <= ref_freq - vco_frequency;  

            // Loop filter logic (simple proportional control)  
            loop_filter <= loop_filter + phase_error;  

            // VCO logic  
            vco_frequency <= loop_filter;  
            vco_out <= (vco_frequency[0] == 1'b1) ? ~vco_out : vco_out;  
        end  
    end  

    // Divide the VCO output by 2  
    assign divided_clk = vco_out;  

endmodule

