module spi_master (
    input wire clk,
    input wire rst,
    input wire start,
    input wire [7:0] data_in,
    output reg mosi,
    output reg sck,
    output reg cs,
    output reg done
);
    reg [2:0] bit_count;
    reg [7:0] shift_reg;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            mosi <= 0;
            sck <= 0;
            cs <= 1;
            done <= 0;
            bit_count <= 0;
            shift_reg <= 0;
        end else if (start) begin
            cs <= 0; // Activate chip select
            shift_reg <= data_in;
            bit_count <= 7; // Start with the most significant bit
            done <= 0;
        end else if (bit_count < 8) begin
            sck <= ~sck; // Generate clock
            if (sck) begin // On the rising edge
                mosi <= shift_reg[bit_count]; // Send the current bit
                bit_count <= bit_count - 1; // Move to the next bit
            end else if (bit_count == 0) begin
                done <= 1; // Data transmission complete
                cs <= 1; // Deactivate chip select
            end
        end
    end
endmodule

