module serializer_32bit(  
    input clk,  
    input rst_n,  
    input [31:0] data_in,  
    output reg serial_out  
);  
    reg [31:0] shift_reg;  
    reg [4:0] bit_counter;  

    always @(posedge clk or negedge rst_n) begin  
        if (!rst_n) begin  
            shift_reg <= 32'b0;  
            serial_out <= 1'b0;  
            bit_counter <= 5'd0;  
        end else if (bit_counter < 32) begin  
            serial_out <= shift_reg[31];  
            shift_reg <= {shift_reg[30:0], 1'b0};  
            bit_counter <= bit_counter + 1;  
        end else begin  
            serial_out <= 1'b0; // output can be idle after 32 bits  
        end  
    end  

    always @(posedge clk or negedge rst_n) begin  
        if (!rst_n) begin  
            shift_reg <= data_in;  
        end  
    end  
endmodule

