module deserializer (
    input wire clk,
    input wire reset,
    input wire serial_in,
    input wire valid,
    output reg [15:0] parallel_out
);
    reg [3:0] bit_count;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            parallel_out <= 16'b0;
            bit_count <= 4'b0;
        end else if (valid && bit_count < 16) begin
            parallel_out <= {serial_in, parallel_out[15:1]};
            bit_count <= bit_count + 1;
        end
    end
endmodule

