module iir_filter(  
    input clk,  
    input reset,  
    input signed [15:0] x,  
    output reg signed [15:0] y  
);  
    // IIR filter coefficients  
    parameter signed [15:0] b0 = 16'h0A00; // Feedforward coefficient  
    parameter signed [15:0] b1 = 16'h0A00;  
    parameter signed [15:0] b2 = 16'h0400;  
    parameter signed [15:0] a1 = 16'hF800; // Feedback coefficient  
    parameter signed [15:0] a2 = 16'hF800;  

    reg signed [15:0] x1, x2;  
    reg signed [15:0] y1, y2;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            y <= 0;  
            x1 <= 0;  
            x2 <= 0;  
            y1 <= 0;  
            y2 <= 0;  
        end else begin  
            // IIR filter equation  
            y <= b0 * x + b1 * x1 + b2 * x2 - a1 * y1 - a2 * y2;  
            // Shift registers  
            x2 <= x1;  
            x1 <= x;  
            y2 <= y1;  
            y1 <= y;  
        end  
    end  
endmodule

